{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * Words are stored in a real trie: one node per distinct prefix, walked by
 * Unicode code point, so an astral character is a single step.
 */

/** A single trie node. */
class TrieNode {
  /** @type {Map<number, TrieNode>} Children keyed by code point. */
  children = new Map();

  /** @type {boolean} Whether a word ends here. */
  terminal = false;

  /** @type {unknown} Value stored for the word ending here. */
  value = undefined;

  /** @type {number} Number of stored words at or below this node. */
  count = 0;
}

/**
 * Asserts a value is a string.
 * @param {unknown} value Value to check.
 * @param {string} label Argument name used in the message.
 * @returns {string} The value, narrowed to string.
 */
function assertString(value, label) {
  if (typeof value !== 'string') throw new TypeError(`${label} must be a string`);
  return value;
}

/**
 * Asserts a limit is Infinity or a non-negative safe integer.
 * @param {unknown} limit Value to check.
 * @returns {number} The validated limit.
 */
function assertLimit(limit) {
  const ok =
    limit === Number.POSITIVE_INFINITY ||
    (typeof limit === 'number' && Number.isSafeInteger(limit) && limit >= 0);
  if (!ok) throw new TypeError('limit must be a non-negative integer');
  return /** @type {number} */ (limit);
}

/**
 * Splits a string into code points.
 * @param {string} text Text to split.
 * @returns {number[]} Code points in order.
 */
function codePointsOf(text) {
  const out = [];
  for (const character of text) out.push(/** @type {number} */ (character.codePointAt(0)));
  return out;
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#root.count;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Walks to the node for a string without creating anything.
   * @param {string} text String to walk.
   * @returns {TrieNode | undefined} Node, or undefined when absent.
   */
  #find(text) {
    let node = this.#root;
    for (const point of codePointsOf(text)) {
      const next = node.children.get(point);
      if (next === undefined) return undefined;
      node = next;
    }
    return node;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    assertString(word, 'word');
    const points = codePointsOf(word);
    const path = [this.#root];
    let node = this.#root;
    for (const point of points) {
      let next = node.children.get(point);
      if (next === undefined) {
        next = new TrieNode();
        node.children.set(point, next);
        this.#nodeCount += 1;
      }
      node = next;
      path.push(node);
    }
    if (node.terminal) {
      const previous = node.value;
      node.value = value;
      return previous;
    }
    node.terminal = true;
    node.value = value;
    for (const visited of path) visited.count += 1;
    return undefined;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    assertString(word, 'word');
    const node = this.#find(word);
    return node !== undefined && node.terminal ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    assertString(word, 'word');
    const node = this.#find(word);
    return node !== undefined && node.terminal;
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    assertString(word, 'word');
    const points = codePointsOf(word);
    const path = [this.#root];
    let node = this.#root;
    for (const point of points) {
      const next = node.children.get(point);
      if (next === undefined) return false;
      node = next;
      path.push(node);
    }
    if (!node.terminal) return false;

    node.terminal = false;
    node.value = undefined;
    for (const visited of path) visited.count -= 1;

    for (let depth = path.length - 1; depth > 0; depth -= 1) {
      const current = path[depth];
      if (current.terminal || current.children.size > 0) break;
      path[depth - 1].children.delete(points[depth - 1]);
      this.#nodeCount -= 1;
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    assertString(prefix, 'prefix');
    const node = this.#find(prefix);
    return node === undefined ? 0 : node.count;
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    assertString(prefix, 'prefix');
    const cap = assertLimit(limit);
    const node = this.#find(prefix);
    const out = [];
    if (node === undefined || cap === 0) return out;
    for (const [word] of this.#walk(node, prefix, cap)) out.push(word);
    return out;
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    return [...this.#walk(this.#root, '', Number.POSITIVE_INFINITY)];
  }

  /**
   * Yields word and value pairs under a node, in code point order.
   * @param {TrieNode} start Node to start from.
   * @param {string} prefix Text leading to that node.
   * @param {number} limit Maximum number of pairs to yield.
   * @yields {[string, unknown]} Word and value pair.
   * @returns {Generator<[string, unknown]>} Ordered pairs.
   */
  *#walk(start, prefix, limit) {
    /** @type {Array<{node: TrieNode, word: string}>} */
    const stack = [{ node: start, word: prefix }];
    let emitted = 0;
    while (stack.length > 0 && emitted < limit) {
      const { node, word } = /** @type {{node: TrieNode, word: string}} */ (stack.pop());
      if (node.terminal) {
        yield [word, node.value];
        emitted += 1;
        if (emitted >= limit) return;
      }
      const points = [...node.children.keys()].sort((a, b) => b - a);
      for (const point of points) {
        stack.push({
          node: /** @type {TrieNode} */ (node.children.get(point)),
          word: word + String.fromCodePoint(point),
        });
      }
    }
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    assertString(text, 'text');
    let node = this.#root;
    let best = null;
    let consumed = '';
    if (node.terminal) best = { word: '', value: node.value };
    for (const character of text) {
      const next = node.children.get(/** @type {number} */ (character.codePointAt(0)));
      if (next === undefined) break;
      node = next;
      consumed += character;
      if (node.terminal) best = { word: consumed, value: node.value };
    }
    return best;
  }
}
