   */
  entries() {
    return [...this.#walk(this.#root, '', Number.POSITIVE_INFINITY)];
  }

  /**
   * Yields word and value pairs under a node, in code point order.
   * @param {TrieNode} start Node to start from.
   * @param {string} prefix Text leading to that node.
   * @param {number} limit Maximum number of pairs to yield.
   * @yields {[string, unknown]} Word and value pair.
   * @returns {Generator<[string, unknown]>} Ordered pairs.
   */
  *#walk(start, prefix, limit) {
    /** @type {Array<{node: TrieNode, word: string}>} */
    const stack = [{ node: start, word: prefix }];
    let emitted = 0;
    while (stack.length > 0 && emitted < limit) {
      const { node, word } = /** @type {{node: TrieNode, word: string}} */ (stack.pop());
      if (node.terminal) {
        yield [word, node.value];
        emitted += 1;
        if (emitted >= limit) return;
      }
      const points = [...node.children.keys()].sort((a, b) => b - a);
      for (const point of points) {
        stack.push({
          node: /** @type {TrieNode} */ (node.children.get(point)),
          word: word + String.fromCodePoint(point),
        });
      }
    }
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    assertString(text, 'text');
    let node = this.#root;
    let best = null;
    let consumed = '';
    if (node.terminal) best = { word: '', value: node.value };
    for (const character of text) {
      const next = node.children.get(/** @type {number} */ (character.codePointAt(0)));
      if (next === undefined) break;
      node = next;
      consumed += character;
      if (node.terminal) best = { word: consumed, value: node.value };
    }
    return best;
  }
}
